/* v15: corrector de contraste por COLOR (sin contornos). Solo toca texto que no llega al mínimo
   legible sobre un fondo opaco conocido; si el fondo es imagen/degradado, lo deja en paz. */
(function(){
  const root=document.documentElement;
  const SKIP='input,textarea,select,option,svg,path,img,video,canvas,script,style';
  // Normaliza CUALQUIER color CSS (rgb, color(srgb ...), color-mix, hex) a rgba 0-255 usando un canvas.
  const cv=document.createElement('canvas');cv.width=cv.height=1;
  const cx=cv.getContext('2d',{willReadFrequently:true});
  const cache=new Map();
  function parse(v){
    v=String(v).trim();if(!v)return null;
    if(cache.has(v))return cache.get(v);
    let out=null;
    try{
      cx.clearRect(0,0,1,1);cx.fillStyle='#000';cx.fillStyle=v;
      const t=cx.fillStyle;cx.clearRect(0,0,1,1);cx.fillStyle=v;cx.fillRect(0,0,1,1);
      const d=cx.getImageData(0,0,1,1).data;
      out={r:d[0],g:d[1],b:d[2],a:d[3]/255};
    }catch(e){out=null}
    cache.set(v,out);return out;
  }
  function lum(c){const f=x=>{x/=255;return x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4)};return .2126*f(c.r)+.7152*f(c.g)+.0722*f(c.b)}
  function ratio(a,b){const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
  function bgOf(el){
    for(let n=el;n&&n.nodeType===1;n=n.parentElement){
      const cs=getComputedStyle(n);
      if(cs.backgroundImage&&cs.backgroundImage!=='none')return null; // degradado/imagen: fondo desconocido
      const c=parse(cs.backgroundColor);
      if(c&&c.a>=.95)return c;
      if(n===root)break;
    }
    return null;
  }
  function clear(){
    document.querySelectorAll('[data-iris-fixed]').forEach(el=>{
      const o=el.getAttribute('data-iris-orig');
      if(o)el.style.setProperty('color',o);else el.style.removeProperty('color');
      el.removeAttribute('data-iris-fixed');el.removeAttribute('data-iris-orig');
    });
  }
  function update(){
    clear();
    const ink=parse(getComputedStyle(root).getPropertyValue('--iris-ink').trim()||'#fff');
    const inkC=ink||{r:255,g:255,b:255,a:1};
    const white={r:255,g:255,b:255,a:1},black={r:12,g:12,b:16,a:1};
    document.querySelectorAll('#publicLayer *').forEach(el=>{
      if(el.children.length||el.matches(SKIP)||el.closest('svg,.theme-swatch')||!(el.textContent||'').trim())return;
      const cs=getComputedStyle(el);
      if(cs.visibility==='hidden'||cs.display==='none')return;
      const fg=parse(cs.color),bg=bgOf(el);
      if(!fg||!bg)return;
      const px=parseFloat(cs.fontSize)||16,bold=(parseInt(cs.fontWeight)||400)>=700;
      const need=(px>=24||(px>=18.66&&bold))?3:4.5;
      if(ratio(fg,bg)>=need)return;
      const pick=[inkC,white,black].filter(c=>ratio(c,bg)>=need).sort((a,b)=>ratio(b,bg)-ratio(a,bg));
      const best=ratio(inkC,bg)>=need?inkC:(pick[0]||(lum(bg)>.4?black:white));
      el.setAttribute('data-iris-fixed','1');
      el.setAttribute('data-iris-orig',el.style.color||'');
      el.style.setProperty('color','rgb('+best.r+','+best.g+','+best.b+')','important');
    });
  }
  let q=false;function schedule(){if(q)return;q=true;requestAnimationFrame(()=>{q=false;update()})}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
  new MutationObserver(m=>{if(m.every(r=>r.target.closest&&r.target.closest('[data-iris-fixed]')&&r.attributeName==='style'))return;schedule()})
    .observe(document.querySelector('#publicLayer')||root,{attributes:true,attributeFilter:['class','hidden','data-theme'],childList:true,subtree:true});
  new MutationObserver(schedule).observe(root,{attributes:true,attributeFilter:['data-theme']});
  document.addEventListener('click',e=>{if(e.target.closest('[data-theme-choice]'))setTimeout(schedule,100)});
  window.addEventListener('pageshow',schedule);window.addEventListener('resize',schedule);
})();



