(function(){
 const candidates=[...document.querySelectorAll('#page-home .legacy-home-content p,#page-history p,#page-departments p,#page-news p')];
 candidates.forEach((el,i)=>{if(i%3===1){const words=el.textContent.trim().split(/\s+/);if(words.length>9){const a=Math.floor(words.length*.28),b=Math.min(words.length-1,a+Math.max(3,Math.floor(words.length*.16)));const before=words.slice(0,a).join(' '),mid=words.slice(a,b+1).join(' '),after=words.slice(b+1).join(' ');el.innerHTML='';if(before)el.append(document.createTextNode(before+' '));const red=document.createElement('span');red.className='iris-redacted';red.textContent=mid;el.append(red);if(after)el.append(document.createTextNode(' '+after));}}});
})();



/* Source script block 8 */

(function(){
  const toggle=document.getElementById('irisMenuToggle');
  const links=document.getElementById('irisNavLinks');
  if(toggle && links){
    toggle.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();const open=!links.classList.contains('is-open');links.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Cerrar menú de navegación':'Abrir menú de navegación');});
    links.addEventListener('click',function(e){const a=e.target.closest('a');if(!a)return;const id=(a.id||'').replace(/^nav-/,'');if(id && typeof window.showPage==='function')window.showPage(id);});
    document.addEventListener('click',function(e){if(!e.target.closest('#irisMainNav')){links.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');}});
    document.addEventListener('keydown',function(e){if(e.key==='Escape'){links.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');}});
  }
  document.querySelectorAll('[data-theme-choice]').forEach(function(button){button.addEventListener('click',function(e){e.preventDefault();if(typeof window.setTheme==='function')window.setTheme(button.dataset.themeChoice);});});
  const names={iris:'IRIS actual',classic:'Clásico original',light:'Claro',dark:'Oscuro',autumn:'Otoño',nox:'Nox',aqua:'Aqua',classified:'Bloody',clearance:'Clearance'};
  if(typeof window.setTheme==='function'){
    const original=window.setTheme;
    window.setTheme=function(theme){if(!names[theme])theme='iris';document.documentElement.dataset.theme=theme;try{localStorage.setItem('iris-public-theme',theme)}catch(e){}document.querySelectorAll('[data-theme-choice]').forEach(function(b){b.classList.toggle('selected',b.dataset.themeChoice===theme)});};
  }
  try{const saved=localStorage.getItem('iris-public-theme');if(saved&&names[saved]){document.documentElement.dataset.theme=saved;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===saved));}}catch(e){}
})();



/* IRIS Release V20: multi-page navigation and shared theme persistence */
(function(){
  const pageFiles = {
    history: 'historia.html',
    departments: 'departamentos.html',
    news: 'novedades.html',
    careers: 'carreras.html'
  };
  const mainFile = 'index.html';
  const originalShowPage = window.showPage;
  window.showPage = function(id){
    const local = document.getElementById('page-' + id);
    if (local && typeof originalShowPage === 'function') return originalShowPage(id);
    if (pageFiles[id]) { window.location.href = pageFiles[id]; return false; }
    if (['home','settings','forums'].includes(id)) {
      window.location.href = mainFile + (id === 'home' ? '' : '?page=' + encodeURIComponent(id));
      return false;
    }
    return false;
  };
  function syncTheme(){
    let theme = 'iris';
    try { theme = localStorage.getItem('iris-public-theme') || 'iris'; } catch(e) {}
    document.documentElement.dataset.theme = theme;
    document.querySelectorAll('[data-theme-choice]').forEach(function(b){
      b.classList.toggle('selected', b.dataset.themeChoice === theme);
    });
  }
  syncTheme();
  window.addEventListener('storage', function(e){ if(e.key === 'iris-public-theme') syncTheme(); });
  document.addEventListener('DOMContentLoaded', function(){
    const params = new URLSearchParams(window.location.search);
    const requested = params.get('page');
    if (requested && ['home','settings','forums'].includes(requested) && document.getElementById('page-' + requested) && typeof originalShowPage === 'function') {
      originalShowPage(requested);
    }
    const navMap = {home:mainFile,history:pageFiles.history,departments:pageFiles.departments,news:pageFiles.news,careers:pageFiles.careers};
    document.querySelectorAll('#irisNavLinks a').forEach(function(a){
      const m = (a.getAttribute('onclick') || '').match(/showPage\(['"]([^'"]+)/);
      if (m && navMap[m[1]]) a.setAttribute('href', navMap[m[1]]);
    });
  });
})();
